<?php pageStart('My Claims', $user, 'claims'); ?>
<main class="container"><header class="page-header"><div><h1>My Claims</h1><p>Follow the status of your item return requests.</p></div></header><?php if ($error): ?><div class="alert alert-error"><?= e($error) ?></div><?php endif; ?><section class="card"><div class="report-list"><?php if (!$claims): ?><p class="empty">You have not submitted any claims.</p><?php endif; ?><?php foreach ($claims as $claim): ?><article class="report"><div><h3><?= e($claim['item_name']) ?></h3><p><?= e($claim['category']) ?> · <?= e($claim['location']) ?></p><p><?= e($claim['claim_details']) ?></p></div><span class="badge badge-<?= e($claim['status']) ?>"><?= e(ucfirst($claim['status'])) ?></span></article><?php endforeach; ?></div></section></main><?php pageEnd(); ?>